    choose: [['She asserts a need (for / of) independence.', 'for'], ['A person can set a limit without (rejecting / rejected) someone.', 'rejecting'], ['They may maintain contact on different (terms / termed).', 'terms'], ['Emi discusses the principle without (identifying / identified) the source.', 'identifying'], ['Akari has (signed / signing) the lease.', 'signed'], ['A signed lease does not by itself confirm a completed (move / moved).', 'move']],
