export const closedDoorsId = (number: StoryLessonNumber) => `conversational-skills-L8-C2-${number}-${closedDoorsEpisodes[number].skill}-en-v1`;

export function buildClosedDoorsLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildEnglishExpressionLesson(number, closedDoorsEpisodes[number], previous, reference, {
    id: closedDoorsId(number), chapterName: 'Behind Closed Doors', pronunciation: closedDoorsPronunciation[number],
    setting: 'Aokawa, a fictional neighbourhood in Tokyo. Emi’s podcast team has private conversations with residents, reviews editorial choices and meets at Daisuke’s café as financial pressure and possible redevelopment emerge.',
    previousSummary: index === 0 ? smilesEpisodes[9].closing : closedDoorsEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: `${conversationalLanguageInstructions(8)}\nReference: The Things We Don’t Say, Chapter 2: Behind Closed Doors. Keep TOEIC 785–940 visible label and owner range. Eight episodes map to slots 1-4 and 6-9, with 5/10 dynamic checkpoints. English only, four Step A expressions, Step B-only pronunciation with precise bold stress, no Part III or extra commentary. Short tutor-first dialogue, objective first, plain Apply situations, separate questions, private listening, fresh visible reading notes, fixed English feedback. No new artwork, romance, external model APIs or app AI credits. Continue Emi, Riku, Hana, Leila and Daisuke; no invented medical/legal qualifications or nationalities. Akari is the name in the outline, with actual real name unprovided and withheld; Monday exchanges lead to private conversation, family financial difficulty, pressure to contribute beyond means, already discussed several times. No publication or recording permission inferred; business loan/redevelopment is unknown until final episode. Yuko forty-two, divorced three years earlier, partners’ priorities differ; regrets failed relationship but not accepting ending. No fault finding, abuse, infidelity, reconciliation or public permission invented. Jun reports supervisor humiliation/career threats and fears losing family income; asks information about options, declines recorded interview. No complaint, employer identity, investigation, legal finding or guaranteed protection. A week later Akari refuses savings for another expense; support/respect discussed generally with Daisuke, without identifying source or making universal family law. Café twenty years, higher operating costs, weak business, unpaid bills; Daisuke privately accepts Riku help reviewing resources and asks confidentiality. Property-management envelope contents unknown; no rent arrears, bankruptcy, funding, debt amount or closure inferred. Akari decides apartment to gain independence while wanting contact/help when possible, not punishment; later text confirms lease signed, not completed move or reconciliation. Hana discusses broader boundary principle without identifying details. Leila’s publication proposal never becomes a leak: removing name not permission and circumstances may identify; team excludes private Akari disclosures and plans general discussion with explicitly consenting participants. No replacement interviews/episode yet. Two weeks later Akari privately adds father’s loan/repayment trouble tied to family business and possible redevelopment. No official notice to parents, neighbours reportedly contacted; more understanding does not mean solving every problem or ending boundaries. Explicit do not publish, Emi promises. Later landlord letter tells Daisuke owner considering redevelopment and lease may not renew, some businesses notified. No confirmed eviction, closing date, legal ruling, shared building/landlord/project or relocation plan. Emi must not share Akari’s private details with Daisuke or publicise either account without permission. End with broader questions and uncertainty, not a resolved redevelopment or new published exposé.`,
  });
  lesson.storyData.storyTitle = 'The Things We Don’t Say';
  lesson.storyData.characters = [
    { id: 'emi', name: 'Emi Sato', role: 'main', description: 'Independent podcast journalist who listens privately, respects recording and publication choices, and distinguishes reported concerns from confirmed outcomes.' },
    { id: 'riku', name: 'Riku', role: 'supporting', description: 'Community organiser who introduces Jun, supports careful editorial review and offers confidential help with café support resources.' },
    { id: 'hana', name: 'Hana', role: 'supporting', description: 'Friend who discusses reporting risks and boundaries. She receives no identifying details about Akari in the broader discussion; no professional qualification is supplied.' },
    { id: 'leila', name: 'Leila', role: 'supporting', description: 'Podcast producer who considers family-pressure coverage and acknowledges why Akari’s private material must remain excluded.' },
    { id: 'daisuke', name: 'Daisuke', role: 'supporting', description: 'Café owner of twenty years, privately facing rising costs and weak business before a landlord letter raises uncertainty about redevelopment and renewal.' },
    { id: 'akari', name: 'Akari', role: 'supporting', description: 'Name used for the private listener in the outline; actual real name withheld. She seeks financial boundaries, signs a lease and explicitly refuses public use of her later family-business account.' },
    { id: 'yuko', name: 'Yuko', role: 'supporting', description: 'Forty-two-year-old who divorced three years earlier and distinguishes sadness about the marriage’s outcome from regret about accepting its end.' },
    { id: 'jun', name: 'Jun', role: 'supporting', description: 'Office worker who describes supervisor mistreatment and dependence on his income, asks for information and declines a recorded interview.' },
  ];
  return { ...lesson, course: 'conversational-skills', level: 8, chapter: 2, lessonNumber: number,
    levelBadge: 'TOEIC 785–940', chapterLabel: 'Chapter 2: Behind Closed Doors', status: previous.status || 'draft',
    overlayColor: previous.overlayColor || '#17252bcc', supportLanguage: 'en', authoringLanguageTarget: 'TOEIC 785-940', authoringLanguageRevision: 'toeic-v1' };
}

export function buildClosedDoorsChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildClosedDoorsLesson(number, {}, reference));
}
